import heapq


def kthNearest(points, queries):
    out = []
    for qx, qy, k in queries:
        heap = []
        for i, (x, y) in enumerate(points):
            key = (-((x - qx) ** 2 + (y - qy) ** 2), -i)
            if len(heap) < k:
                heapq.heappush(heap, key)
            elif key > heap[0]:
                heapq.heapreplace(heap, key)
        out.append(-heap[0][1])
    return out
